              }
            }
          }
        }
      }
    },
    "/contact.email.get": {
      "post": {
        "summary": "Called with the customer number; gives back the registered e-mail / phone.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "data": {
                    "type": "object",
                    "properties": {
                      "customerNo": {"type": "string", "description": "Customer number, e.g. 90000001. May be sent as a string or as a number."},
                      "intAddressInfoType": {"type": "string", "enum": ["E", "P", "B"], "description": "\"E\" e-mail, \"P\" phone, \"B\" both. An empty value gives a 400."}
                    },
                    "required": ["customerNo", "intAddressInfoType"]
                  },
                  "call": {
                    "type": "object",
                    "description": "Call metadata the bank logs; ignored by the test environment.",
                    "properties": {
                      "ani": {"type": "string", "description": "Caller's number."},
                      "lang": {"type": "string", "description": "Call language, e.g. \"tr\"."}
                    }
                  }
                },
                "required": ["data"]
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Success when result.returnCode is \"1\". Errors (no data object): 400 INVALID_ARGUMENTS_ERROR, 500 FBE00099.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "data": {
                      "type": "object",
                      "properties": {
                        "communicationType": {"type": "string", "description": "E.g. \"Both\", or \"Phone\" when only a phone is registered."},
                        "ibanCountryCode": {"type": "string", "description": "Phone country code (the iban prefix is historical, nothing to do with IBANs)."},
                        "ibanAreaCode": {"type": "string", "description": "Phone area code."},
                        "ibanPhoneNum": {"type": "string", "description": "Phone number."},
                        "ibanEmail": {"type": "string", "description": "The registered e-mail address; empty string when no e-mail is registered."},
